',NULL,NULL,NULL,'','2020-12-13 17:51:12',NULL,NULL),(1607881932306,0,0,99999,NULL,0,3,NULL,'@raw 自定义 SQL 片段','SELECT','POST','JSON','/get','{   // 类似 12306 根据始发站和到达站来过滤火车班次，班次和线路多对一，线路和站点多对多
    "sql@": {
        "from": "Comment",
        "join": "&/Comment:to/userId@",
        "Comment": {  // 假装是始发站
            "@column": "userId",
            "content~": "a",  // 假装是站点名
            "momentId>": "to.momentId",
            "@raw": "momentId>"
        },
        "Comment:to": {  // 假装是终点站
            "userId@": "/Comment/userId",
            "@column": "",
            "content~": "j"  // 假装是站点名
        }
    },
    "[]": {
        "Moment": {  // 假装是班次
            "userId{}@": {
                "from": "User",
                "User": {  // 假装是线路
                    "id{}@": "sql",
                    "@column": "id"
                }
            }
        }
    },
    "@explain": true
}
                                                                                                                                                                                                              
',NULL,NULL,NULL,'','2020-12-13 17:52:12',NULL,NULL),(1608995763278,0,0,99999,NULL,0,3,NULL,'SQL 函数与表达式','SELECT','POST','JSON','/get','{
